function applyCustomerModuleOrder(b){
  const home=$('customer-home'),map={contact:$('public-business-info'),profile:$('customer-profile'),campaigns:$('cards'),rewards:$('rewards'),appointments:$('appointment-box')};
  const device=(window.matchMedia&&window.matchMedia('(max-width:899px)').matches)?'mobile':'desktop';
  const defaults=device==='mobile'?{contact:100,profile:100,campaigns:100,rewards:100,appointments:100}:{contact:100,profile:50,campaigns:50,rewards:50,appointments:50};
  const widths={...defaults},positions={contact:1,profile:1,campaigns:1,rewards:1,appointments:1},saved=b['module_widths_'+device];
  if(saved&&typeof saved==='object'){
    for(const [key,value] of Object.entries(saved))if(key in widths&&Number(value))widths[key]=Number(value);
  }else for(const row of String(saved||'').split(',')){
    const [key,value,start]=row.split(':');
    if(key in widths&&Number(value)){widths[key]=Number(value);if(Number(start))positions[key]=Number(start)}
  }
  for(const [key,el] of Object.entries(map))if(el){
    const span=Math.max(3,Math.min(12,Math.round(widths[key]/100*12)));
    const start=Math.max(1,Math.min(13-span,positions[key]||1));
    el.dataset.publicModule=key;
    el.classList.toggle('module-compact',widths[key]<=50);
    el.style.setProperty('--module-span',span);
    el.style.setProperty('--module-start',start);
    el.style.setProperty('--module-order',String(String(b['module_order_'+device]||'').split(',').indexOf(key)+1));
  }
  for(const key of String(b['module_order_'+device]||'').split(','))if(map[key])home.appendChild(map[key]);
}
