async function loadPublicBranding(){try{
  const r=await fetch(`/api/public/${slug}/branding?refresh=${Date.now()}`,{cache:'no-store'});
  if(!r.ok)throw Error(`branding_${r.status}`);
  hidePublicPageDisabled();
  const b=await r.json(),wasLoaded=!!publicBrandingFingerprint;
  const fingerprint=JSON.stringify(b);
  if(fingerprint!==publicBrandingFingerprint){publicBrandingFingerprint=fingerprint;applyPublicBranding(b);if(wasLoaded&&token)showHome().catch(()=>{})}
}catch(e){if(e.message==='branding_404'){showPublicPageDisabled();return}console.warn('No se pudo cargar la personalización del negocio',e)}}
async function loadPublicBranches(){try{const rows=await fetch(`/api/public/${slug}/branches`).then(r=>r.ok?r.json():[]);if(!rows.length)return;const label=document.createElement('label');label.innerHTML=`Sucursal que visitas<select id="customer-branch"><option value="">Selecciona una sucursal</option>${rows.map(b=>`<option value="${b.id}">${b.name}${b.city?' · '+b.city:''}</option>`).join('')}</select>`;$('customer-phone').closest('label').after(label)}catch(e){}}
async function identifyFromDirectory(){try{const saved=JSON.parse(localStorage.getItem('negrosky_global_customer')||'null');if(!saved?.name||!saved?.phone)return false;const r=await api(`/api/public/${slug}/identify`,{method:'POST',body:JSON.stringify({name:saved.name,phone:saved.phone,marketing_consent:false,branch_id:null})});token=r.access_token;localStorage.setItem(`customer_${slug}`,token);document.documentElement.classList.add('customer-session');$('identify-box')?.classList.add('hidden');return true}catch(e){return false}}
function openWhatsAppOptIn(name,phone,blankWindow){const number=String(publicBranding?.whatsapp_number||'').replace(/\D/g,'');if(!number)return false;const message=`Hola, quiero recibir promociones e información por WhatsApp. Mi nombre es ${String(name||'').trim()}.`;const url=`https://wa.me/${number}?text=${encodeURIComponent(message)}`;if(blankWindow)blankWindow.location.href=url;else window.open(url,'_blank','noopener');localStorage.setItem(`negrosky_whatsapp_optin_${slug}_${String(phone).replace(/\D/g,'')}`,'1');return true}
$('identify-form').onsubmit=async e=>{e.preventDefault();const wantsWhatsApp=$('consent').checked;const name=$('customer-name').value.trim(),phone=$('customer-phone').value.replace(/\D/g,'');let whatsappWindow=null;if(wantsWhatsApp&&publicBranding?.whatsapp_number)whatsappWindow=window.open('about:blank','_blank');try{const r=await api(`/api/public/${slug}/identify`,{method:'POST',body:JSON.stringify({name,phone,marketing_consent:wantsWhatsApp,branch_id:+($('customer-branch')?.value||0)||null})});token=r.access_token;localStorage.setItem(`customer_${slug}`,token);localStorage.setItem('negrosky_global_customer',JSON.stringify({name,phone}));document.documentElement.classList.add('customer-session');$('identify-box')?.classList.add('hidden');$('customer-home')?.classList.add('hidden');await loadPublicBranding();if(wantsWhatsApp&&!openWhatsAppOptIn(name,phone,whatsappWindow)&&whatsappWindow)whatsappWindow.close();await showHome()}catch(x){if(whatsappWindow)whatsappWindow.close();$('customer-error').textContent=x.message;showToast(x.message,'error')}};
function rewardAvailability(c){if(c.reward_stock!==null&&c.rewards_remaining===0)return'<div class="exhausted-card"><div>⛔</div><h3>Premios agotados</h3><p>Agradecemos tu interés. Esta campaña ha entregado todos los premios disponibles.</p></div>';if(c.reward_display==='unlimited')return'<p class="reward-availability">🎁 Premios ilimitados</p>';if(c.reward_display==='quantity')return`<p class="reward-availability">🎁 Quedan <b>${c.rewards_remaining}</b> de ${c.reward_stock} premios</p>`;return''}
function rewardGroups(rewards){const groups={};rewards.filter(r=>r.status==='available').forEach(r=>{const k=`${r.program_id}_${r.name}`;(groups[k]??={...r,count:0}).count++});return Object.values(groups)}
function syncAutomaticModules({hasRewards=false,hasAppointments}={}){
  // La disponibilidad real manda: el cliente no ve módulos vacíos.
  $('cards')?.classList.toggle('hidden',!customerModuleEnabled('loyalty'));
  $('rewards')?.classList.toggle('hidden',!customerModuleEnabled('loyalty')||!hasRewards);
  if(typeof hasAppointments==='boolean')setAppointmentVisibility(customerModuleEnabled('appointments')&&hasAppointments);
  else if(!customerModuleEnabled('appointments'))setAppointmentVisibility(false);
}
const loyaltyCardMarkup = c => window.NegroskyCard.render({...c,button_label:publicBranding?.button_label});
async function showHome(){try{const d=await api('/api/public/me/cards');localStorage.setItem('negrosky_global_customer',JSON.stringify({name:d.customer.name,phone:d.customer.phone}));if(d.enabled_modules)applyCustomerModuleVisibility(d.enabled_modules);$('identify-box').classList.add('hidden');$('customer-home').classList.remove('hidden');$('hello').textContent=`¡Hola, ${d.customer.name}!`;setupCustomerInstall();setupCustomerPush();$('cards').innerHTML=d.cards.length?d.cards.map(loyaltyCardMarkup).join(''):'<div class="hero-card"><p>Aún no hay tarjetas activas.</p></div>';const groups=rewardGroups(d.rewards);$('rewards').innerHTML=groups.map(g=>`<div class="loyalty-card"><p class="eyebrow">PREMIOS DISPONIBLES · ${g.program_name}</p><h2>${g.name}</h2><p>Tienes <b>${g.count}</b> premio${g.count===1?'':'s'} para reclamar.</p><label>¿Cuántos deseas reclamar?<select id="reward-qty-${g.program_id}">${Array.from({length:g.count},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select></label><button class="full" onclick="rewardBatch(${g.program_id},+document.getElementById('reward-qty-${g.program_id}').value)">Reclamar premio${g.count===1?'':'s'}</button></div>`).join('');syncAutomaticModules({hasRewards:groups.length});}catch(e){localStorage.removeItem(`customer_${slug}`);token=null}}
let baseHomePromise=null;const renderHomeWithSession=showHome;showHome=async function(){if(baseHomePromise)return baseHomePromise;baseHomePromise=(async()=>{await renderHomeWithSession();if(!token){document.documentElement.classList.remove('customer-session');document.documentElement.classList.remove('customer-ready');$('identify-box')?.classList.remove('hidden');$('customer-home')?.classList.add('hidden')}})();try{return await baseHomePromise}finally{baseHomePromise=null}}
function formatDate(value){if(!value)return'';const normalized=value.includes('T')?value:value.replace(' ','T')+'Z';return new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short',hour12:true}).format(new Date(normalized))}
async function loadHistory(){const h=await api('/api/public/me/history');$('history-summary').innerHTML=`<div class="history-stat"><b>${h.summary.purchases}</b><span>Compras</span></div><div class="history-stat"><b>${h.summary.rewards_earned}</b><span>Premios ganados</span></div><div class="history-stat"><b>${h.summary.rewards_claimed}</b><span>Premios reclamados</span></div>`;const events=[...h.purchases.map(p=>({type:'purchase',date:p.created_at,title:'Compra validada',detail:`${p.program_name} · ${p.branch_name}`})),...h.rewards.map(r=>({type:'reward',date:r.claimed_at||r.unlocked_at,title:r.status==='used'?'Premio reclamado':'Premio ganado',detail:`${r.name}${r.branch_name?' · '+r.branch_name:''}`}))].sort((a,b)=>new Date(b.date)-new Date(a.date));$('history-list').innerHTML=events.length?events.map(e=>`<div class="history-item ${e.type==='reward'?'reward':''}"><p><b>${e.title}</b></p><p>${e.detail}</p><p class="history-date">${formatDate(e.date)}</p></div>`).join(''):'<p class="muted">Todavía no hay movimientos.</p>'}
async function displayQr(result,renew){
  $('customer-home').classList.add('hidden');$('qr-modal').classList.remove('hidden');
  const showCode=next=>{result=next;const direct=result.worker_url||`${location.origin}/worker?code=${result.code}`;$('qr-image').classList.remove('hidden');$('qr-code').classList.remove('hidden');$('countdown').parentElement.classList.remove('hidden');$('qr-image').style.opacity=1;$('qr-code').style.opacity=1;$('qr-image').src=`/api/qr/${result.code}.png?t=${Date.now()}`;$('qr-code').textContent=result.code.replace(/^(\d{3})(\d{3})$/,'$1 $2');$('qr-link').href=direct;$('qr-link').textContent=direct};
  showCode(result);
  const status=$('customer-operation-status');status.className='status-panel pending';status.textContent='Esperando validación del trabajador…';
  let n=result.expires_in_seconds||60,renewing=false;$('countdown').textContent=n;
  const refreshCode=async()=>{if(renewing)return;renewing=true;status.className='status-panel pending';status.textContent='Renovando QR y código automáticamente…';try{const next=await renew();showCode(next);n=next.expires_in_seconds||60;$('countdown').textContent=n;status.textContent='Código renovado. Esperando validación del trabajador…';showToast('Nuevo QR y código disponibles.')}catch(e){status.className='status-panel error';status.textContent='No se pudo renovar. Reintentando automáticamente…'}finally{renewing=false}};
  const countdown=setInterval(()=>{n=Math.max(0,n-1);$('countdown').textContent=n;if(n===0)refreshCode()},1000);
  const polling=setInterval(async()=>{const checkedCode=result.code;try{const check=await api(`/api/public/me/operation-status/${checkedCode}`);if(check.status==='validated'){clearInterval(polling);clearInterval(countdown);const completed=result.operation==='purchase'&&check.mission_completed;showToast(completed?'¡Misión completada! Ya puedes reclamar tu premio.':'Operación validada correctamente.','success');$('operation-title').textContent=completed?'¡Misión completada!':result.operation==='purchase'?'¡Compra validada!':'¡Premio entregado!';status.className=completed?'mission-complete':'validation-success';status.innerHTML=completed?`<div class="confetti">🎉 ✨ 🎊 ⭐ 🎉</div><div class="trophy">🏆</div><h2>¡Misión completada!</h2><p>Ganaste: <b>${check.reward_name}</b></p><button class="claim-button" onclick="location.reload()">Ver y reclamar mi premio</button>`:`<div class="success-check">✓</div><h2>¡Validación exitosa!</h2><p>${result.operation==='purchase'?`Nuevo progreso: ${check.progress}/${check.target}`:'Premio entregado correctamente'}</p>`;$('qr-image').classList.add('hidden');$('qr-code').classList.add('hidden');$('countdown').parentElement.classList.add('hidden');successSound();if(navigator.vibrate)navigator.vibrate([180,70,180])}else if(check.status==='expired'&&checkedCode===result.code){refreshCode()}}catch(e){status.className='status-panel error';status.textContent='No se pudo consultar la validación.'}},1200);
}
function operationError(message){showToast(message,'error');const banner=$('service-banner');banner.classList.remove('hidden');banner.innerHTML=`<div class="service-icon">⚠️</div><h2>No fue posible generar el código</h2><p>${message}</p><small>Tu progreso no fue modificado.</small>`;banner.scrollIntoView({behavior:'smooth',block:'center'})}
async function purchase(id){armSound();const renew=()=>api('/api/public/me/purchase-token',{method:'POST',body:JSON.stringify({program_id:id})});try{await displayQr(await renew(),renew)}catch(e){operationError(e.message)}}
async function rewardBatch(programId,quantity){armSound();const renew=()=>api('/api/public/me/rewards/batch-token',{method:'POST',body:JSON.stringify({program_id:programId,quantity})});try{await displayQr(await renew(),renew)}catch(e){operationError(e.message)}}
