let serviceOpen=true;
function renderCustomerServiceState(open,message){const content=$('customer-schedule-content');if(!content)return;let state=$('customer-service-state');if(!state){state=document.createElement('div');state.id='customer-service-state';content.prepend(state)}state.className=open?'service-state open':'service-state closed';state.innerHTML=open?'🟢 <b>En servicio</b>':`🔴 <b>Fuera de servicio</b><p>${ES.escape(message||'En este momento el negocio está cerrado.')}</p>`}
async function syncCustomerScheduleStatus(){if(!token)return;try{const profile=await api('/api/public/me/cards'),branch=profile.customer.origin_branch_id,state=await fetch(`/api/public/${slug}/service-status${branch?'?branch_id='+branch:''}`,{cache:'no-store'}).then(r=>r.json());renderCustomerServiceState(!!state.open,state.message)}catch(e){}}
async function checkServiceStatus(){if(!token)return;try{const profile=await api('/api/public/me/cards');const branch=profile.customer.origin_branch_id;const state=await fetch(`/api/public/${slug}/service-status${branch?'?branch_id='+branch:''}`).then(r=>r.json());serviceOpen=!!state.open;const banner=$('service-banner');if(state.open){banner.classList.add('hidden')}else{banner.classList.remove('hidden');banner.innerHTML=`<div class="service-icon">🌙</div><h2>Fuera de servicio</h2><p>${state.message}</p><small>Tu progreso y tus premios permanecen guardados.</small>`}document.querySelectorAll('.loyalty-card button').forEach(button=>{if(!button.textContent.includes('agotados'))button.disabled=!state.open})}catch(e){}}
async function showCampaignNotice(){if(!token||!customerModuleEnabled('loyalty'))return;try{const profile=await api('/api/public/me/cards');if(!profile.cards.length){$('cards').innerHTML='<div class="no-campaigns"><div>✨</div><h2>Próximamente nuevas campañas</h2><p>En este momento no hay campañas de fidelización disponibles. Cuando el negocio active una, aparecerá aquí automáticamente.</p><small>Tu cuenta y tu información permanecen registradas.</small></div>'}}catch(e){}}
async function loadCustomerCollaborations(){try{const response=await fetch(`/api/public/${encodeURIComponent(customerPathSlug)}/collaborations`,{cache:'no-store'});if(!response.ok)return;const rows=await response.json();const item=rows.find(x=>!sessionStorage.getItem(`negrosky_collaboration_${customerPathSlug}_${x.id}`));if(!item)return;sessionStorage.setItem(`negrosky_collaboration_${customerPathSlug}_${item.id}`,'1');const seconds=Math.max(1,Math.min(60,Number(item.ad_seconds)||5));const overlay=document.createElement('div');overlay.className='collaboration-overlay';overlay.innerHTML=`<article class="collaboration-ad"> <button type="button" class="collaboration-close" aria-label="Cerrar">×</button><p class="eyebrow">COLABORACIÓN · ${ES.escape(item.partner_name||'Negocio aliado')}</p><h2>${ES.escape(item.title)}</h2>${item.image_url?`<img src="${ES.escape(item.image_url)}" alt="Publicidad de colaboración">`:''}<p>${ES.escape(item.message||'Conoce esta promoción especial.')}</p><small>Esta publicidad se cerrará en ${seconds} segundos.</small></article>`;document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.collaboration-close').onclick=close;setTimeout(close,seconds*1000)}catch(e){}}
