const originalShowHome=showHome;let sessionHomePromise=null;showHome=async function(){if(sessionHomePromise)return sessionHomePromise;sessionHomePromise=(async()=>{await originalShowHome();if(!token)return;await Promise.all([checkServiceStatus(),syncCustomerScheduleStatus(),showCampaignNotice(),loadAppointmentModule(),loadCustomerRaffles(),loadCustomerCollaborations()])})();try{return await sessionHomePromise}finally{sessionHomePromise=null}};
