async function loadCustomerAppointmentServices(){
  const branchId=+$('customer-appointment-branch').value;
  if(!branchId)return;
  try{const services=await api(`/api/public/${slug}/appointment-services?branch_id=${branchId}`);if(!services.length){setAppointmentVisibility(false);$('customer-calendar-days').textContent='No hay citas disponibles para esta sucursal.';$('customer-appointment-service').innerHTML='<option value="">Sin servicios configurados</option>';$('appointment-availability').textContent='Todavía no hay servicios de citas disponibles en esta sucursal. Consulta al negocio.';$('customer-appointment-time').innerHTML='<option value="">Sin horas disponibles</option>';$('next-appointment-date').classList.add('hidden');return}setAppointmentVisibility(true);$('customer-appointment-service').innerHTML=services.map(s=>`<option value="${s.id}">${ES.escape(s.name)} · duración aproximada: ${s.duration_minutes} minutos${s.price===null?'':' · $'+Number(s.price).toLocaleString('es-CO')}</option>`).join('');await loadAppointmentDates()}catch(e){setAppointmentVisibility(false)}
}
let customerMonth=null;
function renderCustomerDates(data){
  const month=data.month,[year,number]=month.split('-').map(Number);
  const first=(new Date(Date.UTC(year,number-1,1)).getUTCDay()+6)%7;
  const count=new Date(Date.UTC(year,number,0)).getUTCDate();
  $('customer-calendar-month').textContent=new Intl.DateTimeFormat('es-CO',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,number-1,1)));
  const selected=$('customer-appointment-date').value;
  const cells=Array.from({length:first},()=>'<span class="calendar-empty"></span>');
  for(let day=1;day<=count;day++){
    const date=`${month}-${String(day).padStart(2,'0')}`,available=data.days[date]||0;
    cells.push(`<button type="button" class="calendar-date ${selected===date?'selected':''}" data-book-date="${date}" ${available?'':'disabled'}><b>${day}</b>${available?`<small>${available} cupo${available===1?'':'s'}</small>`:''}</button>`)
  }
  $('customer-calendar-days').innerHTML='<div class="calendar-weekdays">'+['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>`<b>${x}</b>`).join('')+'</div><div class="calendar-grid">'+cells.join('')+'</div>';
  if(!data.days[selected]){$('customer-appointment-date').value='';$('customer-appointment-time').innerHTML='<option value="">Escoge una fecha primero</option>'}
  const chosen=$('customer-appointment-date').value;
  $('customer-chosen-date').textContent=chosen?`Fecha seleccionada: ${new Intl.DateTimeFormat('es-CO',{dateStyle:'full',timeZone:'UTC'}).format(new Date(chosen+'T12:00:00Z'))}`:'Selecciona un día disponible';
  $('customer-calendar-prev').disabled=month<=ES.dayKey(new Date(),data.timezone).slice(0,7);
  $('customer-calendar-next').disabled=month>=ES.dayKey(new Date(Date.now()+180*86400000),data.timezone).slice(0,7);
  if(!Object.keys(data.days).length)$('appointment-availability').textContent='Este mes no tiene citas disponibles. Revisa el mes siguiente.';
}
async function loadAppointmentDates(){
  const branch=+$('customer-appointment-branch').value,service=+$('customer-appointment-service').value;
  if(!branch||!service)return;
  customerMonth??=ES.dayKey(new Date(),customerTimeZone).slice(0,7);
  const month=customerMonth;
  $('customer-calendar-days').textContent='Buscando fechas disponibles…';
  try{const data=await api(`/api/public/${slug}/appointment-calendar?branch_id=${branch}&service_id=${service}&month=${month}`);
    if(branch!==+$('customer-appointment-branch').value||service!==+$('customer-appointment-service').value||month!==customerMonth)return;
    customerTimeZone=data.timezone;renderCustomerDates(data);
    if($('customer-appointment-date').value)await loadAppointmentAvailability();
  }catch(e){$('customer-calendar-days').textContent=e.message;showToast(e.message,'error')}
}
$('customer-calendar-days').onclick=event=>{const button=event.target.closest('[data-book-date]');if(!button||button.disabled)return;$('customer-appointment-date').value=button.dataset.bookDate;$('customer-chosen-date').textContent=`Fecha seleccionada: ${new Intl.DateTimeFormat('es-CO',{dateStyle:'full',timeZone:'UTC'}).format(new Date(button.dataset.bookDate+'T12:00:00Z'))}`;document.querySelectorAll('[data-book-date]').forEach(item=>item.classList.toggle('selected',item===button));loadAppointmentAvailability()};
function moveCustomerMonth(offset){const [year,number]=(customerMonth||ES.dayKey(new Date(),customerTimeZone).slice(0,7)).split('-').map(Number);const next=new Date(Date.UTC(year,number-1+offset,1));customerMonth=`${next.getUTCFullYear()}-${String(next.getUTCMonth()+1).padStart(2,'0')}`;$('customer-appointment-date').value='';$('customer-appointment-time').innerHTML='<option value="">Escoge una fecha primero</option>';loadAppointmentDates()}
$('customer-calendar-prev').onclick=()=>moveCustomerMonth(-1);
$('customer-calendar-next').onclick=()=>moveCustomerMonth(1);
async function loadAppointmentAvailability(){
  const date=$('customer-appointment-date').value,branch=+$('customer-appointment-branch').value,service=+$('customer-appointment-service').value;
  const select=$('customer-appointment-time');select.innerHTML='<option value="">Selecciona una fecha y servicio</option>';$('next-appointment-date').classList.add('hidden');
  if(!date||!branch||!service)return;
  try{const data=await api(`/api/public/${slug}/appointment-availability?branch_id=${branch}&service_id=${service}&date=${encodeURIComponent(date)}`);
    if(date!==$('customer-appointment-date').value||branch!==+$('customer-appointment-branch').value||service!==+$('customer-appointment-service').value)return;
    customerTimeZone=data.timezone;const available=data.slots.filter(x=>x.available).length;
    select.innerHTML='<option value="">Selecciona una hora disponible</option>'+data.slots.filter(x=>x.available).map(x=>`<option value="${x.starts_at}">${ES.clock(x.time)}</option>`).join('');
    const next=$('next-appointment-date');next.classList.toggle('hidden',available>0||!data.next_available_date);next.dataset.date=data.next_available_date||'';
    if(!available){$('appointment-availability').textContent=data.next_available_date?`No quedan citas disponibles el ${date}. El próximo día con cupos es ${data.next_available_date}.`:`No quedan citas disponibles el ${date}. Prueba con otra fecha.`;showToast('No hay más citas ese día. Elige el próximo día disponible.')}else $('appointment-availability').textContent=`${available} hora(s) disponible(s). Horario local del negocio. Elige la hora que prefieras.`;
  }catch(e){select.innerHTML='<option value="">Sin horarios disponibles</option>';$('appointment-availability').textContent=e.message;showToast(e.message,'error')}
}
async function loadMyAppointments(){
  try{const rows=await api('/api/public/me/appointments');$('customer-appointments').innerHTML=rows.length?'<h3>Mis citas</h3>'+rows.map(x=>{
    const active=['scheduled','confirmed'].includes(x.status)&&new Date(x.starts_at)>new Date();
    const delayed=x.delay_minutes?`<p class="delay-warning">Demora aproximada: ${x.delay_minutes} minutos. Fin estimado: ${ES.appointmentTime(x.estimated_end_at,x.tenant_timezone)}.</p>`:'';
    const cancel=x.status==='cancelled'&&x.cancellation_reason?`<p>Motivo de cancelación: ${ES.escape(x.cancellation_reason)}</p>`:'';
    return `<div class="history-item"><p><b>${ES.escape(x.service_name)}</b> · ${ES.appointmentStates[x.status]||ES.escape(x.status)}</p><p>${ES.escape(x.branch_name)}${x.city?' · '+ES.escape(x.city):''}</p><p>Duración aproximada: ${x.duration_minutes} minutos</p><p class="history-date">${ES.dateTime(x.starts_at,x.tenant_timezone)}</p>${delayed}${cancel}${active?`<details class="cancel-appointment"><summary>Cancelar esta cita</summary><form data-cancel-id="${x.id}"><label>Cuéntanos el motivo<textarea name="reason" rows="2" minlength="5" maxlength="500" required placeholder="Ejemplo: no podré asistir ese día"></textarea></label><button type="submit" class="secondary full">Confirmar cancelación</button></form></details>`:''}</div>`
  }).join(''):''}catch(e){$('customer-appointments').textContent='No fue posible consultar tus citas.'}
}
$('customer-appointments').addEventListener('submit',async event=>{
  const form=event.target.closest('form[data-cancel-id]');if(!form)return;
  event.preventDefault();const button=form.querySelector('button');button.disabled=true;
  try{await api(`/api/public/me/appointments/${form.dataset.cancelId}/cancel`,{method:'POST',body:JSON.stringify({reason:form.elements.reason.value.trim()})});showToast('Tu cita quedó cancelada. El horario volvió a estar disponible.','success');await Promise.all([loadMyAppointments(),loadAppointmentDates()])}
  catch(e){showToast(e.message,'error');button.disabled=false}
});
async function loadAppointmentModule(){
  if(!token||!customerModuleEnabled('appointments')){setAppointmentVisibility(false);return}
  try{const [profile,locations]=await Promise.all([api('/api/public/me/cards'),fetch(`/api/public/${slug}/branches`).then(r=>r.json())]);if(!locations.length)return;$('customer-appointment-branch').innerHTML=locations.map(b=>`<option value="${b.id}">${b.name}${b.city?' · '+b.city:''}</option>`).join('');if(profile.customer.origin_branch_id&&locations.some(b=>b.id===profile.customer.origin_branch_id))$('customer-appointment-branch').value=profile.customer.origin_branch_id;
    await Promise.all([loadCustomerAppointmentServices(),loadMyAppointments()])}catch(e){}
}
