let lastCustomerNotice=null,customerNoticeBusy=false;
async function pollCustomerNotices(){if(!token||!customerModuleEnabled('notifications')||customerNoticeBusy||document.hidden)return;customerNoticeBusy=true;try{const cursor=lastCustomerNotice===null?'':`?after_id=${lastCustomerNotice}`;const data=await api('/api/public/me/notifications'+cursor);lastCustomerNotice=data.last_id;data.items.forEach(x=>showToast(x.title+': '+x.message,'success',x.image_url||''))}catch(e){}finally{customerNoticeBusy=false}}
