const rouletteRoot=document.querySelector('main.mobile-shell');if(rouletteRoot&&!document.getElementById('customer-roulette'))rouletteRoot.insertAdjacentHTML('beforeend','<section id="customer-roulette" class="hero-card hidden"><p class="eyebrow">MÓDULO INDEPENDIENTE · RULETA DE SUERTE</p><h2>🎡 Ruleta de suerte</h2><p class="muted">Gira y descubre tu premio.</p><div id="customer-roulette-list"></div></section>');applyCustomerModuleVisibility(customerModules);
async function loadCustomerRoulette(){const box=$('customer-roulette'),list=$('customer-roulette-list');if(!customerModuleEnabled('roulette')){box?.classList.add('hidden');if(list)list.replaceChildren();return}try{const rows=await api('/api/public/me/roulette');if(!box||!list)return;box.classList.toggle('hidden',!rows.length);list.innerHTML=rows.map(r=>`<div class="loyalty-card roulette-game-card"><h3>${r.name}</h3><p>Prueba tu suerte y descubre si ganas un premio.</p><button type="button" class="roulette-play-button" onclick="openCustomerRoulette(${r.id})">JUGAR</button><div id="roulette-game-${r.id}" class="roulette-game hidden"><div class="customer-wheel-slot" id="customer-wheel-${r.id}"></div><button type="button" onclick="customerSpin(${r.id})">GIRAR</button><p id="roulette-result-${r.id}" class="roulette-result"></p></div></div>`).join('');rows.forEach(r=>{const slot=$('customer-wheel-'+r.id);if(slot)slot.appendChild(publicWheel054(r.prizes))})}catch(e){}}
window.openCustomerRoulette=id=>{document.getElementById('roulette-game-'+id)?.classList.remove('hidden');document.querySelector('.roulette-play-button[onclick="openCustomerRoulette('+id+')"]')?.classList.add('hidden')};
function rouletteSound(win){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.type=win?'sine':'sawtooth';o.frequency.value=win?660:150;g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.18,c.currentTime+.05);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+(win?5:.8));o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+(win?5:.8))}
window.customerSpin=async id=>{const wheel=document.querySelector('#customer-wheel-'+id+' .negrosky-wheel'),result=document.getElementById('roulette-result-'+id);if(wheel){wheel.style.transition='transform 4s cubic-bezier(.12,.75,.18,1)';wheel.style.transform='rotate(1440deg)'}try{const r=await api('/api/public/me/roulette/'+id+'/spin',{method:'POST'});setTimeout(()=>{const win=!/intenta|pierde|perder/i.test(r.prize);result.textContent=win?'🎉 ¡Ganaste: '+r.prize+'!':'😔 No ganaste esta vez: '+r.prize;result.className='roulette-result '+(win?'win':'lose');rouletteSound(win)},4000)}catch(e){showToast(e.message,'error')}};
loadCustomerRoulette();
setTimeout(()=>{if(token){loadCustomerRoulette();loadCustomerRaffles()}},3000);
function publicWheel054(prizes){const stage=document.createElement('div');stage.className='wheel-stage';const el=document.createElement('div');el.className='negrosky-wheel';const pointer=document.createElement('span');pointer.className='wheel-pointer';pointer.textContent='▼';const colors=['#8b5cf6','#ec4899','#06b6d4','#f59e0b','#10b981','#ef4444'];el.style.background='conic-gradient('+prizes.map((_,i)=>colors[i%colors.length]+' '+(i*100/prizes.length)+'% '+((i+1)*100/prizes.length)+'%').join(',')+')';el.innerHTML=prizes.map((p,i)=>'<span class="wheel-label" style="transform:rotate('+((i+.5)*360/prizes.length)+'deg) translateY(-72px) rotate('+(-((i+.5)*360/prizes.length))+'deg)">'+p+'</span>').join('');stage.append(pointer,el);return stage}
async function loadCustomerRaffles(){if(!token||!customerModuleEnabled('raffles'))return;try{const rows=await api('/api/public/me/raffles'),host=$('rewards');if(!host)return;let box=$('customer-raffles');if(!box){box=document.createElement('section');box.id='customer-raffles';box.className='hero-card';host.after(box)}box.innerHTML=rows.map(r=>`<div class="raffle-card"><p class="eyebrow">🎟️ RIFA</p><h2>${ES.escape(r.name)}</h2><p>${ES.escape(r.description||'Participa en el sorteo.')}</p><p><b>${r.tickets_per_purchase||1}</b> boleta(s) por compra · ${r.ticket_count?'Disponibles: '+r.tickets_available:'Boletas ilimitadas'}</p><p>Mis boletas: <b>${r.my_tickets}</b>${r.customer_ticket_limit?' · Límite: '+r.customer_ticket_limit:''}</p><button type="button" onclick="participateCustomerRaffle(${r.id})">Participar</button></div>`).join('');box.classList.toggle('hidden',!rows.length)}catch(e){}}
window.participateCustomerRaffle=async id=>{try{const r=await api('/api/public/me/raffles/'+id+'/participate',{method:'POST'});showToast(r.message,'success');await loadCustomerRaffles()}catch(e){showToast(e.message,'error')}};

// Public modules are resolved from the page URL, never from a stale customer session.
async function loadCustomerRoulette(){const box=$('customer-roulette'),list=$('customer-roulette-list');if(!customerModuleEnabled('roulette')){box?.classList.add('hidden');return}try{const response=await fetch(`/api/public/${slug}/roulette`,{cache:'no-store'});const rows=response.ok?await response.json():[];if(!box||!list)return;box.classList.toggle('hidden',!rows.length);list.innerHTML=rows.map(r=>`<div class="loyalty-card roulette-game-card"><h3>${r.name}</h3><p>Prueba tu suerte y descubre si ganas un premio.</p><button type="button" class="roulette-play-button" onclick="openCustomerRoulette(${r.id})">JUGAR</button><div id="roulette-game-${r.id}" class="roulette-game hidden"><div class="customer-wheel-slot" id="customer-wheel-${r.id}"></div><button type="button" onclick="customerSpin(${r.id})">GIRAR</button><p id="roulette-result-${r.id}" class="roulette-result"></p></div></div>`).join('');rows.forEach(r=>{const slot=$('customer-wheel-'+r.id);if(slot)slot.appendChild(publicWheel054(r.prizes))})}catch(e){box?.classList.add('hidden')}}
async function loadCustomerRaffles(){if(!customerModuleEnabled('raffles'))return;try{const response=await fetch(`/api/public/${slug}/raffles`,{cache:'no-store'});const rows=response.ok?await response.json():[],host=$('rewards');if(!host)return;let box=$('customer-raffles');if(!box){box=document.createElement('section');box.id='customer-raffles';box.className='hero-card';host.after(box)}box.innerHTML=rows.map(r=>`<div class="raffle-card"><p class="eyebrow">🎟️ RIFA</p><h2>${ES.escape(r.name)}</h2><p>${ES.escape(r.description||'Participa en el sorteo.')}</p><p><b>${r.tickets_per_purchase||1}</b> boleta(s) por compra · ${r.ticket_count?'Disponibles: '+r.tickets_available:'Boletas ilimitadas'}</p><button type="button" onclick="participateCustomerRaffle(${r.id})">Participar</button></div>`).join('');box.classList.toggle('hidden',!rows.length)}catch(e){}}

