// Publicidad global del Administrador General: aparece una vez por campaña y negocio.
async function loadCustomerPlatformAds(){if(!token)return;try{const rows=await fetch(`/api/public/${encodeURIComponent(slug)}/platform-ads`,{cache:'no-store'}).then(r=>r.ok?r.json():[]);const item=rows.find(x=>!sessionStorage.getItem(`negrosky_platform_ad_${slug}_${x.id}`));if(!item)return;sessionStorage.setItem(`negrosky_platform_ad_${slug}_${item.id}`,'1');const seconds=Math.max(1,Math.min(60,Number(item.ad_seconds)||5));const overlay=document.createElement('div');overlay.className='collaboration-overlay platform-ad-overlay';overlay.innerHTML=`<article class="collaboration-ad platform-ad"><button type="button" class="collaboration-close" aria-label="Cerrar">×</button><p class="eyebrow">PUBLICIDAD NEGROSKY</p><h2>${ES.escape(item.title||'Promoción especial')}</h2>${item.image_url?`<img src="${ES.escape(item.image_url)}" alt="Publicidad">`:''}<p>${ES.escape(item.message||'')}</p><small>Esta publicidad se cerrará en ${seconds} segundos.</small></article>`;document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.collaboration-close').onclick=close;setTimeout(close,seconds*1000)}catch(e){}}
const showHomeBeforePlatformAds=showHome;showHome=async function(){const result=await showHomeBeforePlatformAds();if(token)await loadCustomerPlatformAds();return result};
// Varias campañas se muestran en cola, nunca como ventanas superpuestas.
async function loadCustomerPlatformAds(){if(!token)return;try{const rows=await fetch(`/api/public/${encodeURIComponent(slug)}/platform-ads`,{cache:'no-store'}).then(r=>r.ok?r.json():[]);for(const item of rows){if(sessionStorage.getItem(`negrosky_platform_ad_${slug}_${item.id}`))continue;sessionStorage.setItem(`negrosky_platform_ad_${slug}_${item.id}`,'1');const seconds=Math.max(1,Math.min(60,Number(item.ad_seconds)||5));await new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='collaboration-overlay platform-ad-overlay';overlay.innerHTML=`<article class="collaboration-ad platform-ad"><button type="button" class="collaboration-close" aria-label="Cerrar">×</button><p class="eyebrow">PUBLICIDAD NEGROSKY</p><h2>${ES.escape(item.title||'Promoción especial')}</h2>${item.image_url?`<img src="${ES.escape(item.image_url)}" alt="Publicidad">`:''}<p>${ES.escape(item.message||'')}</p><small>Esta publicidad se cerrará en ${seconds} segundos.</small></article>`;document.body.appendChild(overlay);let closed=false;const close=()=>{if(closed)return;closed=true;overlay.remove();resolve()};overlay.querySelector('.collaboration-close').onclick=close;setTimeout(close,seconds*1000)})}}catch(e){}}
